import React, { useState } from "react";
import { motion } from "motion/react";
import { ChevronLeft, ChevronRight } from "lucide-react";

const DEFAULT_ASSETS = [
  { src: 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=600&q=80', title: 'Sunset Beach' },
  { src: 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=600&q=80', title: 'Misty Mountains' },
  { src: 'https://images.unsplash.com/photo-1447752875215-b2761acb3c5d?auto=format&fit=crop&w=600&q=80', title: 'Forest Trail' },
  { src: 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=600&q=80', title: 'Sunlight in Woods' },
  { src: 'https://images.unsplash.com/photo-1501854140801-50d01698950b?auto=format&fit=crop&w=600&q=80', title: 'Green Hills' },
];

interface CardCarouselProps {
  hovered?: boolean;
  className?: string;
  images?: { src: string; title: string }[];
  isMonochrome?: boolean;
}

export const CardCarousel = React.memo(function CardCarousel({
  hovered,
  className = '',
  images = DEFAULT_ASSETS,
  isMonochrome = false
}: CardCarouselProps) {
  const [activeIndex, setActiveIndex] = useState(2);
  const active = hovered !== undefined ? hovered : true;

  const toPrev = (e: React.MouseEvent) => {
    e.stopPropagation();
    setActiveIndex(prev => Math.max(0, prev - 1));
  };

  const toNext = (e: React.MouseEvent) => {
    e.stopPropagation();
    setActiveIndex(prev => Math.min(images.length - 1, prev + 1));
  };

  return (
    <div className={`relative w-[280px] h-[190px] flex flex-col items-center justify-between p-3 select-none ${className}`}>
      <div className="relative w-full h-[140px] flex items-center justify-center border-0 overflow-visible">
        {images.map((img, i) => {
          const offset = i - activeIndex;
          const absOffset = Math.abs(offset);
          const rotateZ = active ? offset * 12 : offset * 4;
          const translateX = active ? offset * 52 : offset * 24;
          const translateY = active ? absOffset * 6 : absOffset * 2;
          const scale = active ? 1 - absOffset * 0.1 : 1 - absOffset * 0.05;
          const zIndex = 20 - absOffset;

          return (
            <motion.div
              key={i}
              onClick={(e) => { e.stopPropagation(); setActiveIndex(i); }}
              initial={false}
              animate={{
                x: translateX,
                y: translateY,
                rotateZ,
                scale,
                zIndex,
              }}
              transition={{ type: 'spring', stiffness: 260, damping: 22 }}
              className="absolute top-0 w-[110px] h-[135px] rounded-xl overflow-hidden shadow-xl border border-white/20 cursor-pointer bg-neutral-900 origin-bottom"
            >
              <img src={img.src} alt={img.title} className="w-full h-full object-cover" />
            </motion.div>
          );
        })}
      </div>
      <div className="flex items-center gap-3 z-30">
        <button onClick={toPrev} className="p-1.5 rounded-full bg-white/10 hover:bg-white/20 text-white transition-colors">
          <ChevronLeft className="w-4 h-4" />
        </button>
        <div className="flex items-center gap-1.5">
          {images.map((_, i) => (
            <div key={i} className={`h-1.5 rounded-full transition-all ${i === activeIndex ? 'w-4 bg-white' : 'w-1.5 bg-white/40'}`} />
          ))}
        </div>
        <button onClick={toNext} className="p-1.5 rounded-full bg-white/10 hover:bg-white/20 text-white transition-colors">
          <ChevronRight className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
});
